    result = [-1] * n
    queue = deque()

    # Initialize the queue with positions where moves are 0
    for i in range(n):
        if result[i] == -1:
            queue.append((i, 0))
            result[i] = 0

    while queue:
        current_position, current_moves = queue.popleft()
        current_value = a[current_position]

        # Check possible moves
        possible_moves = [current_position - current_value, current_position + current_value]

        for new_position in possible_moves:
